const rows=$input.all().map(i=>i.json);
const raw={};
for(const r of rows){ if(r&&r.key!=null) raw[r.key]=r.value; }
function arr(v){ try{ const p=JSON.parse(v); return Array.isArray(p)?p:[]; }catch(e){ return []; } }
function num(v,d){ const n=parseFloat(v); return isNaN(n)?d:n; }
const config={
  niche:{ searchTerms:arr(raw['niche.searchTerms']), excludeNamePatterns:arr(raw['niche.excludeNamePatterns']) },
  classifier:{ model: raw['classifier.model']||'claude-haiku-4-5-20251001', maxTokens:num(raw['classifier.maxTokens'],1024), batchSize:num(raw['classifier.batchSize'],25), rubric:{ hot:raw['classifier.rubric.hot']||'', warm:raw['classifier.rubric.warm']||'', discard:raw['classifier.rubric.discard']||'' } },
  presence:{ reviewVelocityWindowDays:num(raw['presence.reviewVelocityWindowDays'],180), lowVelocityFractionOfCityMedian:num(raw['presence.lowVelocityFractionOfCityMedian'],0.35) },
  routing:{ defaultRouteOnNoMatch: raw['routing.defaultRouteOnNoMatch']||'DM' },
  email:{ patterns:arr(raw['email.patterns']), scrapePaths:arr(raw['email.scrapePaths']) },
  verification:{ enabled:(raw['verification.enabled']==='true') }
};
return [{ json:{ config } }];

const cfg=$('Parse config').first().json.config;
const windowDays=cfg.presence.reviewVelocityWindowDays||180;
const lowFrac=cfg.presence.lowVelocityFractionOfCityMedian||0.35;
const now=Date.now();
const windowMs=windowDays*86400000;
function recentCount(reviewsJson){ let arr=[]; try{ arr=JSON.parse(reviewsJson||'[]'); }catch(e){ arr=[]; } let c=0; for(const r of arr){ const d=Date.parse(r&&r.date); if(!isNaN(d)&&(now-d)<=windowMs) c++; } return c; }
let allRows=[]; try{ allRows=$('Read all leads').all().map(i=>i.json); }catch(e){ allRows=[]; }
if(!allRows.length){ allRows=$input.all().map(i=>i.json); }
const byCity={};
for(const row of allRows){ const city=row.city||''; if(!byCity[city]) byCity[city]=[]; byCity[city].push(recentCount(row.reviews_json)); }
function median(a){ if(!a.length) return 0; const s=[...a].sort((x,y)=>x-y); const m=Math.floor(s.length/2); return s.length%2?s[m]:(s[m-1]+s[m])/2; }
const medianByCity={}; for(const c in byCity){ medianByCity[c]=median(byCity[c]); }
const out=[];
for(const item of $input.all()){
  const row=item.json;
  let reviews=[]; try{ reviews=JSON.parse(row.reviews_json||'[]'); }catch(e){ reviews=[]; }
  let sig={}; try{ sig=JSON.parse(row.signals||'{}'); }catch(e){ sig={}; }
  const recentReviews=recentCount(row.reviews_json);
  const cityMedianRecent=medianByCity[row.city||'']||0;
  const facts={ hasWebsite:!!row.website, bookingLinksCount:Array.isArray(sig.bookingLinks)?sig.bookingLinks.length:0, claimed:sig.claimed===true, imagesCount:sig.imagesCount||0, hasHours:sig.hasHours===true, recentReviews, cityMedianRecent, lowVelocity:recentReviews<(cityMedianRecent*lowFrac), reviewCount:row.review_count||0, rating:row.rating||0, latestReviewDate:row.latest_review_date||'' };
  out.push({ json:{ ...row, reviewsParsed:reviews, facts } });
}
return out;

const cfg=$('Parse config').first().json.config;
let paths=(cfg.email&&Array.isArray(cfg.email.scrapePaths)&&cfg.email.scrapePaths.length)?cfg.email.scrapePaths.slice():['/'];
if(paths.indexOf('/')<0) paths=['/'].concat(paths);
const out=[];
for(const item of $input.all()){
  const row=item.json;
  let origin='';
  { const w=String(row.website||'').trim(); const wp=w?(/^https?:\/\//i.test(w)?w:('https://'+w)):''; const m=wp.match(/^(https?:\/\/[^\/?#]+)/i); origin=m?m[1]:''; }
  const seen={}; let count=0;
  for(const p of paths){
    if(!origin) break;
    let full;
    full=origin+(String(p).startsWith('/')?String(p):'/'+String(p));
    if(seen[full]) continue; seen[full]=true;
    const isRoot=(full===origin+'/');
    out.push({ json:{ place_id:row.place_id, _fetchUrl:full, _isRoot:isRoot, _lead:row } });
    count++;
  }
  if(!count){ out.push({ json:{ place_id:row.place_id, _fetchUrl:origin?origin+'/':'https://invalid.invalid/', _isRoot:true, _lead:row } }); }
}
return out;

const inputs=$('Expand fetch targets').all();
const responses=$input.all();
const EXCLUDES=['example.','sentry','wix','wordpress','.png','.jpg','.webp','@2x','cloudflare','godaddy','user@domain','@domain.com','yourname','yourdomain','your@','name@email','email@address','noreply','no-reply','donotreply','placeholder','schema.org','@example','test@test','filler@'];
function extract(html){
  if(!html||typeof html!=='string') return [];
  const found={};
  const mailtoRx=/mailto:([^\s'>]+)/gi; let m;
  while((m=mailtoRx.exec(html))){ found[m[1]]=true; }
  const rx=/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi; let g;
  while((g=rx.exec(html))){ found[g[0]]=true; }
  const clean=[];
  for(let e of Object.keys(found)){ e=String(e).toLowerCase().trim().split('?')[0]; e=e.replace(/^[^a-z0-9]+/,'').replace(/[^a-z]+$/,''); if(!e) continue; if(!/^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/.test(e)) continue; if(EXCLUDES.some(x=>e.indexOf(x)>=0)) continue; if(clean.indexOf(e)<0) clean.push(e); }
  return clean;
}
function extractSocials(html){ if(!html||typeof html!=='string') return []; const out=[]; const rx=/https?:\/\/(?:www\.)?(?:facebook\.com|instagram\.com|linkedin\.com|x\.com|twitter\.com|tiktok\.com)\/[A-Za-z0-9_.\/-]+/gi; let m; while((m=rx.exec(html))){ let u=m[0].replace(/[\/.,)]+$/,''); const lo=u.toLowerCase(); if(/sharer|\/share|intent|\/plugins|\/dialog|\/login|\/hashtag|\/p\/|\/reel|\/posts\/|\/photo|\/watch|\/status\/|\/2008\/|profile\.php/.test(lo)) continue; if(/facebook\.com\/tr$/.test(lo)) continue; if(out.indexOf(u)<0) out.push(u); if(out.length>=8) break; } return out; }
const groups={};
for(let i=0;i<inputs.length;i++){
  const meta=inputs[i].json; const resp=responses[i]?responses[i].json:null; const pid=meta.place_id;
  if(!groups[pid]) groups[pid]={ lead:meta._lead, alive:false, emails:[], socials:[] };
  let status=null, body='';
  if(resp&&typeof resp==='object'){ if(typeof resp.statusCode==='number') status=resp.statusCode; const rawBody=(resp.data!=null)?resp.data:resp.body; if(rawBody!=null) body=(typeof rawBody==='string')?rawBody:JSON.stringify(rawBody); }
  else if(typeof resp==='string'){ body=resp; }
  const ok=(status!=null&&status>=200&&status<400);
  if(ok) groups[pid].alive=true;
  if(ok){ for(const e of extract(body)){ if(groups[pid].emails.indexOf(e)<0) groups[pid].emails.push(e); } for(const s of extractSocials(body)){ if(groups[pid].socials.indexOf(s)<0) groups[pid].socials.push(s); } }
}
const out=[];
for(const pid in groups){ const g=groups[pid]; out.push({ json:{ ...g.lead, websiteAlive:g.alive, scrapedEmails:g.emails, socialLinks:g.socials } }); }
return out;

const cfg=$('Parse config').first().json.config;
const c=cfg.classifier;
const q=String.fromCharCode(34);
const shape='{'+q+'classification'+q+':'+q+'HOT'+q+'|'+q+'WARM'+q+'|'+q+'DISCARD'+q+','+q+'evidence'+q+':[{'+q+'quote'+q+':'+q+'...'+q+','+q+'date'+q+':'+q+'...'+q+','+q+'source'+q+':'+q+'review'+q+'|'+q+'owner_response'+q+'}],'+q+'reasons'+q+':'+q+'one sentence'+q+'}';
const sys='You classify UK physiotherapy clinic leads for a booking-recovery agency. Apply the three rubrics exactly. Rubric HOT: '+(c.rubric.hot||'')+' Rubric WARM: '+(c.rubric.warm||'')+' Rubric DISCARD: '+(c.rubric.discard||'')+' Respond with STRICT JSON only, no prose, matching: '+shape+'. Evidence quotes MUST be copied verbatim from the supplied review texts or owner responses. HOT without at least one verbatim quote is invalid - use WARM or DISCARD instead. Never place a double-quote character inside any JSON string value; for WARM verdicts based on facts, phrase the quote as a short plain-English description with no quotation marks.';
const out=[];
for(const item of $input.all()){
  const row=item.json;
  const reviews=(row.reviewsParsed||[]).map(r=>({ text:r.text, date:r.date, stars:r.stars, ownerResponse:r.ownerResponse, ownerResponseDate:r.ownerResponseDate }));
  const userMsg='Classify this clinic lead.\nName: '+(row.name||'')+'\nCity: '+(row.city||'')+'\nFacts (JSON): '+JSON.stringify(Object.assign({},row.facts||{},{websiteAlive:row.websiteAlive===true,scrapedEmailsFound:(Array.isArray(row.scrapedEmails)?row.scrapedEmails.length:0)}))+'\nReviews (JSON array): '+JSON.stringify(reviews);
  const body={ model:c.model, max_tokens:c.maxTokens, temperature:0, system:sys, messages:[{ role:'user', content:userMsg }] };
  out.push({ json:{ ...row, classifierBody:JSON.stringify(body) } });
}
return out;

const src=$('Build classifier request').all();
const responses=$input.all();
function norm(s){ return String(s||'').replace(/\s+/g,' ').trim().toLowerCase(); }
const out=[];
for(let i=0;i<responses.length;i++){
  const row=src[i]?src[i].json:{};
  const resp=responses[i]?responses[i].json:{};
  let text='';
  try{ if(resp&&Array.isArray(resp.content)){ text=resp.content.map(b=>(b&&b.text)?b.text:'').join('').trim(); } }catch(e){}
  let verdict=null;
  if(text){ let t=text.trim(); if(t.indexOf('```')===0){ t=t.replace(/^```(?:json)?/i,'').replace(/```$/,'').trim(); } try{ verdict=JSON.parse(t); }catch(e){ const m=t.match(/"classification"\s*:\s*"(HOT|WARM|DISCARD)"/i); if(m){ verdict={ classification:m[1].toUpperCase(), evidence:[], reasons:'[salvaged: model emitted invalid JSON]' }; } else { verdict=null; } } }
  let classification, evidence, reasons;
  if(!verdict||typeof verdict!=='object'){ classification='ERROR'; reasons=String(text||JSON.stringify(resp)).slice(0,300); evidence=[]; }
  else{ classification=String(verdict.classification||'ERROR').toUpperCase(); evidence=Array.isArray(verdict.evidence)?verdict.evidence:[]; reasons=String(verdict.reasons||''); }
  const reviews=row.reviewsParsed||[];
  const parts=[];
  for(const r of reviews){ if(r&&r.text) parts.push(norm(r.text)); if(r&&r.ownerResponse) parts.push(norm(r.ownerResponse)); }
  const corpus=parts.join(' | ');
  if(classification==='HOT'){ const kept=evidence.filter(ev=>ev&&ev.quote&&corpus.indexOf(norm(ev.quote))>=0); evidence=kept; if(!kept.length){ classification='WARM'; reasons=reasons+' [downgraded: hot_without_verbatim_evidence]'; } }
  out.push({ json:{ ...row, classification, evidence, reasons } });
}
return out;

const lead=$('HW leads').item.json;
const resp=$json;
const items=(resp&&Array.isArray(resp.items))?resp.items:[];
const STOP=['ltd','limited','llp','physiotherapy','physio','clinic','the','and'];
function toks(s){ return String(s||'').toLowerCase().replace(/[^a-z0-9\s]/g,' ').split(/\s+/).filter(t=>t&&STOP.indexOf(t)<0); }
const nameToks=toks(lead.name);
const nameSet={}; for(const t of nameToks) nameSet[t]=true;
const nameKeys=Object.keys(nameSet);
function overlap(title){ const tt=toks(title); if(!tt.length||!nameKeys.length) return 0; const ts={}; for(const t of tt) ts[t]=true; const tKeys=Object.keys(ts); let inter=0; for(const t of nameKeys){ if(ts[t]) inter++; } const denom=Math.max(nameKeys.length,tKeys.length); return denom?inter/denom:0; }
let best=null, bestScore=0;
for(const it of items){ const status=String(it.company_status||'').toLowerCase(); const type=String(it.company_type||'').toLowerCase(); if(status!=='active') continue; if(['ltd','llp'].indexOf(type)<0) continue; const sc=overlap(it.title); if(sc>=0.6&&sc>bestScore){ best=it; bestScore=sc; } }
const cfg=$('Parse config').first().json.config;
let extra;
if(best){ extra={ matched:true, entity_check:String(best.company_type||'').toLowerCase(), company_number:best.company_number||'', route:'EMAIL', owner_name:'', ch_title:best.title||'', match_score:bestScore }; }
else{ extra={ matched:false, entity_check:'no_match', company_number:'', route:(cfg.routing.defaultRouteOnNoMatch||'DM'), owner_name:'', ch_title:'', match_score:0 }; }
return { json:{ ...lead, ...extra } };

const m=$('Match company').item.json;
const resp=$json;
const items=(resp&&Array.isArray(resp.items))?resp.items:[];
function titleCase(s){ return String(s||'').toLowerCase().replace(/\b\w/g,function(c){ return c.toUpperCase(); }); }
let owner='';
for(const it of items){
  if(it.resigned_on) continue;
  const role=String(it.officer_role||'').toLowerCase();
  if(role!=='director'&&role!=='llp-member') continue;
  const nm=String(it.name||'');
  if(nm.indexOf(',')>=0){ const parts=nm.split(','); const sur=(parts[0]||'').trim(); const firsts=(parts[1]||'').trim().split(/\s+/).filter(Boolean); const first=firsts[0]||''; owner=titleCase((first+' '+sur).trim()); }
  else{ owner=titleCase(nm); }
  if(owner) break;
}
return { json:{ ...m, owner_name:owner } };

const row=$json;
const cfg=$('Parse config').first().json.config;
const patterns=(cfg.email&&Array.isArray(cfg.email.patterns))?cfg.email.patterns:[];
function ascii(s){ return String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/[^a-z]/g,''); }
let domain='';
if(row.websiteAlive&&row.website){ { const m=String(row.website).trim().match(/^(?:https?:\/\/)?([^\/?#:]+)/i); domain=m?m[1].toLowerCase().replace(/^www\./,''):''; } }
let candidates=[];
if(row.owner_name&&domain){
  const cleaned=String(row.owner_name).replace(/\b(dr|mr|mrs|ms|miss|prof)\b\.?/gi,' ').trim().split(/\s+/).filter(Boolean);
  const first=ascii(cleaned[0]||''); const last=ascii(cleaned[cleaned.length-1]||''); const f=first.slice(0,1); const l=last.slice(0,1);
  if(first&&last){ for(const p of patterns){ let e=String(p).replace('{first}',first).replace('{last}',last).replace('{f}',f).replace('{l}',l).replace('{domain}',domain); if(e.indexOf('{')>=0) continue; if(candidates.indexOf(e)<0) candidates.push(e); } }
}
let email='', email_source='none_found';
const FREEMAIL=['gmail.com','outlook.com','hotmail.com','yahoo.com','yahoo.co.uk','icloud.com','btinternet.com','aol.com','live.com','live.co.uk','me.com','sky.com','mail.com'];
const rawScraped=Array.isArray(row.scrapedEmails)?row.scrapedEmails:[];
const scraped=rawScraped.filter(function(e){ const ed=String(e).split('@')[1]||''; return (domain&&(ed===domain||ed.endsWith('.'+domain)||domain.endsWith('.'+ed)))||FREEMAIL.indexOf(ed)>=0; });
if(scraped.length){ email=scraped[0]; email_source='site_scrape'; }
else if(row.route==='EMAIL'&&row.owner_name&&domain&&candidates.length){ email=candidates[0]; email_source='ch_pattern_unverified'; }
const email_status='unverified';
return { json:{ ...row, email, email_source, email_status, emailCandidatesList:candidates, domainUsed:domain } };

const row=$json;
const q=String.fromCharCode(34);
function ev(a){ if(!Array.isArray(a)||!a.length) return ''; return a.map(function(e){ return q+String(e.quote||'')+q+' ('+String(e.date||'')+')'; }).join(' | '); }
let sig={}; try{ sig=JSON.parse(row.signals||'{}'); }catch(e){ sig={}; }
const emailCandidates={ scrapedEmails:Array.isArray(row.scrapedEmails)?row.scrapedEmails:[], candidates:Array.isArray(row.emailCandidatesList)?row.emailCandidatesList:[], chosen:row.email||'', source:row.email_source||'none_found', verification:Array.isArray(row.emailVerification)?row.emailVerification:[] };
const mergedSignals=JSON.stringify({ ...sig, ...(row.facts||{}), websiteAlive:row.websiteAlive===true, socialLinks:Array.isArray(row.socialLinks)?row.socialLinks:[], emailCandidates });
return { json:{ place_id:row.place_id, classification:row.classification, evidence:ev(row.evidence), signals:mergedSignals, entity_check:row.entity_check||'', company_number:row.company_number||'', route:row.route||'', owner_name:row.owner_name||'', email:row.email||'', email_status:row.email_status||'unverified', email_source:row.email_source||'none_found', status:'scored', scored_at:new Date().toISOString() } };

const q=String.fromCharCode(34);
function ev(a){ if(!Array.isArray(a)||!a.length) return ''; return a.map(function(e){ return q+String(e.quote||'')+q+' ('+String(e.date||'')+')'; }).join(' | '); }
const out=[];
for(const item of $input.all()){
  const row=item.json;
  let sig={}; try{ sig=JSON.parse(row.signals||'{}'); }catch(e){ sig={}; }
  const emailCandidates={ scrapedEmails:Array.isArray(row.scrapedEmails)?row.scrapedEmails:[], candidates:[], chosen:'', source:'none_found' };
  const mergedSignals=JSON.stringify({ ...sig, ...(row.facts||{}), emailCandidates });
  out.push({ json:{ place_id:row.place_id, classification:row.classification, evidence:ev(row.evidence), signals:mergedSignals, entity_check:'skipped', company_number:'', route:'', owner_name:'', email:'', email_status:'', email_source:'', status:'scored', scored_at:new Date().toISOString() } });
}
return out;

const cfgItem = $('Parse config').first();
const cfg = (cfgItem && cfgItem.json && cfgItem.json.config) ? cfgItem.json.config : {};
const verifyEnabled = !!(cfg.verification && cfg.verification.enabled === true);
const out = [];
for (const item of $input.all()) {
  const row = item.json;
  const scraped = Array.isArray(row.scrapedEmails) ? row.scrapedEmails.filter(Boolean) : [];
  const patterns = Array.isArray(row.emailCandidatesList) ? row.emailCandidatesList.filter(Boolean) : [];
  const seen = new Set();
  const ordered = [];
  for (const e of scraped) { const key = String(e).trim().toLowerCase(); if (key && !seen.has(key)) { seen.add(key); ordered.push({ email: e, source: 'site_scrape' }); } }
  for (const e of patterns) { const key = String(e).trim().toLowerCase(); if (key && !seen.has(key)) { seen.add(key); ordered.push({ email: e, source: 'ch_pattern' }); } }
  const capped = ordered.slice(0, 5);
  const shouldVerify = verifyEnabled && capped.length > 0;
  if (shouldVerify) {
    capped.forEach(function(c, idx) { out.push({ json: { _verify: true, place_id: row.place_id, candidateEmail: c.email, candidateSource: c.source, candidateIndex: idx, _lead: row } }); });
  } else {
    out.push({ json: { _verify: false, ...row } });
  }
}
return out;

const targets = $('Expand verify targets').all().filter(function(t){ return t.json && t.json._verify === true; });
const results = $input.all();
const groups = new Map();
for (let i = 0; i < targets.length; i++) {
  const t = targets[i].json;
  const r = (results[i] && results[i].json) ? results[i].json : {};
  const placeId = t.place_id;
  if (!groups.has(placeId)) groups.set(placeId, { lead: t._lead || {}, verdicts: [] });
  let result = r.result || (r.error ? 'error' : '');
  if (!result) result = 'error';
  if (r.email && String(r.email).trim().toLowerCase() !== String(t.candidateEmail).trim().toLowerCase()) { result = 'error'; }
  groups.get(placeId).verdicts.push({ email: t.candidateEmail, source: t.candidateSource, index: t.candidateIndex, quality: r.quality || null, result });
}
const out = [];
for (const group of groups.values()) {
  const lead = group.lead;
  const verdicts = group.verdicts.slice().sort(function(a, b) { return a.index - b.index; });
  const okMatch = verdicts.find(function(v) { return v.result === 'ok'; });
  let email = lead.email || '';
  let email_source = lead.email_source || 'none_found';
  let email_status;
  if (okMatch) {
    email = okMatch.email;
    email_status = 'ok';
    email_source = okMatch.source === 'ch_pattern' ? 'ch_pattern_verified' : okMatch.source;
  } else {
    const chosenLower = String(lead.email || '').trim().toLowerCase();
    const chosenVerdict = verdicts.find(function(v) { return String(v.email).trim().toLowerCase() === chosenLower; }) || verdicts[0];
    let status = chosenVerdict ? chosenVerdict.result : 'verify_error';
    if (status === 'disposable') status = 'invalid';
    if (status === 'error' || !status) status = 'verify_error';
    email_status = status;
  }
  out.push({ json: { ...lead, email, email_status, email_source, emailVerification: verdicts, _verify: true } });
}
return out;
